# building iperf command options based on iperf configuration dict
import re


class CmdOptions:
    """Managing iperf command options generation."""
    def __init__(self, traffic_definition, configuration):
        """
        Basic initialization.

        :param traffic_definition: definition of data transfer characteristics - transfer & protocol params
        :param configuration: iperf environment configuration (client and server hosts, etc.) - iperf params
        """
        self.traffic_definition = traffic_definition
        self.configuration = configuration

    @property
    def protocol(self):
        """Requested protocol of data transfer"""
        return self.traffic_definition['protocol']

    @property
    def protocol_str(self):
        """Protocol string to be used for composing iperf command string"""
        if self.protocol == 'udp':
            return ' -u'
        if self.protocol == 'tcp':
            return ''
        # raise AttributeError("iperf works only for tcp/udp protocols and not '{}'".format(self.protocol))

    @property
    def port(self):
        """Port to use for iperf command"""
        iperf_port = self._get_config_value('port', default_value='5001')
        iperf_port = int(iperf_port)
        return iperf_port

    @property
    def direction(self):
        """Direction of data transfer ('ul', 'dl' or 'simultaneous_ul_dl')"""
        # Options related to protocol only (not iperf command options) come from traffic definition
        return self.traffic_definition['direction']

    @property
    def buffer_length(self):
        """Buffer length to use for iperf command"""
        # Options that are iperf-specific come from configuration
        try:
            buffer_length = self.configuration['iperf']['buffer_length']
        except KeyError:
            buffer_length = ''
        return buffer_length

    @property
    def window_size(self):
        """Window size to use for iperf command"""
        # Options that are protocol-related and also exist as iperf-option may come from both places
        return self._get_config_value('window_size')

    @staticmethod
    def _to_bool(value):
        false_val = [False, 'False', 'FALSE', 'false']
        if value in false_val:
            value = False
        else:
            value = True
        return value

    @property
    def print_mss(self):
        """Print mss option to use for iperf command"""
        try:
            print_mss = self.configuration['iperf']['print_mss']
            print_mss = self._to_bool(print_mss)
        except KeyError:
            print_mss = False
        return print_mss

    @property
    def set_mss(self):
        """Set mss option to use for iperf command"""
        try:
            if 'set_mss' in self.traffic_definition['protocol_details']:  # to speak in protocol terms (not iperf names)
                set_mss = self.traffic_definition['protocol_details']['set_mss']  # should be rather 'maximum_segment_size'
            else:
                set_mss = self.configuration['iperf']['set_mss']
        except KeyError:
            set_mss = ''
        return set_mss

    @property
    def no_delay(self):
        """No delay option to use for iperf command"""
        no_delay = self._get_config_value('no_delay', default_value='False')
        no_delay = self._to_bool(no_delay)
        return no_delay

    @property
    def time_to_live(self):
        """Time-to-live option to use for iperf command"""
        return self._get_config_value('time_to_live')

    @property
    def type_of_service(self):
        """Type of service option to use for iperf command"""
        return self._get_config_value('type_of_service')

    def _get_config_value(self, config_key, default_value=''):
        """Return config value as string. Traffic definition may overwrite value from config."""
        try:
            if config_key in self.traffic_definition['protocol_details']:
                config_value = self.traffic_definition['protocol_details'][config_key]
            else:
                config_value = self.configuration['iperf'][config_key]
        except KeyError:
            config_value = default_value
        return config_value

    @property
    def parallel(self):
        """Parallel option to use for iperf command"""
        try:
            parallel = self.configuration['iperf']['parallel']
        except KeyError:
            parallel = ''
        return parallel

    @property
    def interval(self):
        """Interval option to use for iperf command"""
        try:
            iperf_interval = float(self.configuration['iperf']['interval'])
        except KeyError:
            iperf_interval = 1
        return iperf_interval

    @property
    def duration(self):
        """Duration option to use for iperf command"""
        return self.traffic_definition['duration']

    @property
    def requested_ul_throughput(self):
        """Throughput requested for UL"""
        return self.traffic_definition['ul_throughput']

    @property
    def requested_dl_throughput(self):
        """Throughput requested for DL"""
        return self.traffic_definition['dl_throughput']

    def client_bandwidth_str(self, direction):
        """Bandwidth option to use for building iperf client command string"""
        if self.protocol != 'udp':
            return ''  # only iperf3 allows "-b" for TCP
        # we always run iperf in kbits/sec since requested throughput is in such units
        bandwidth = self.requested_ul_throughput if direction == 'ul' else self.requested_dl_throughput
        return f' -b {bandwidth}k'

    def server_bandwidth_str(self):
        """Bandwidth option to use for building iperf server command string"""
        if self.protocol != 'udp':
            return ''  # only iperf3 allows "-b" for TCP
        # we use bandwidth parameter on server side only if:
        # 1) it works as client (--dualtest)
        # 2) requested ul and dl throughput differ
        if (self.direction == 'simultaneous_ul_dl') and (self.requested_ul_throughput != self.requested_dl_throughput):
            bandwidth = self.requested_dl_throughput
            # we always run iperf in kbits/sec since requested throughput is in such units
            return f' -b {bandwidth}k'
        return ''

    _re_ipv6 = re.compile(r"^[a-fA-F0-9:]+$")

    # maybe use https://netaddr.readthedocs.io/en/latest/api.html  netaddr.valid_ipv6()
    # but that builds another module dependency
    @staticmethod
    def is_ipv6(ip):
        """Check if IP has IPv6 format"""
        return CmdOptions._re_ipv6.match(ip)

    def client_options(self, client_ip, server_ip, port=None):
        """Generate options for iperf client command"""
        port = port if port else self.port
        use_ipv6 = " -V" if self.is_ipv6(server_ip) else ""
        client_direction = 'dl' if self.direction == 'dl' else 'ul'
        dualtest = " --dualtest" if self.direction == 'simultaneous_ul_dl' else ''
        buffer_len = f" -l {self.buffer_length}" if self.buffer_length else ''
        window_size = f" -w {self.window_size}" if self.window_size else ''
        print_mss = " -m" if self.print_mss else ''
        set_mss = f" -M {self.set_mss}" if self.set_mss else ''
        no_delay = " -N" if self.no_delay else ''
        time_to_live = f" -T {self.time_to_live}" if self.time_to_live else ''
        type_of_service = f" -S {self.type_of_service}" if self.type_of_service else ''
        parallel = f" -P {self.parallel}" if self.parallel else ''
        arguments = [
            f"-c {server_ip}{use_ipv6}{self.protocol_str}",
            f" -p {port}",
            f" -B {client_ip}",
            f" -f k{parallel}",
            f" -i {self.interval}",
            f" -t {self.duration}",
            dualtest,
            self.client_bandwidth_str(client_direction),
            buffer_len,
            window_size,
            print_mss,
            set_mss,
            no_delay,
            time_to_live,
            type_of_service,
        ]
        options = "".join(arguments)
        return options

    def server_options(self, client_ip, server_ip, port=None):
        """Generate options for iperf server command"""
        port = port if port else self.port
        use_ipv6 = " -V" if self.is_ipv6(client_ip) else ""
        # Note (https://github.com/esnet/iperf/issues/267) in iperf2 buffer_len is server reading buffer size
        buffer_len = f" -l {self.buffer_length}" if self.buffer_length else ''
        window_size = f" -w {self.window_size}" if self.window_size else ''
        print_mss = " -m" if self.print_mss else ''
        set_mss = f" -M {self.set_mss}" if self.set_mss else ''
        no_delay = " -N" if self.no_delay else ''
        parallel = f" -P {self.parallel}" if self.parallel else ' -P 1'
        arguments = [
            f"-s{use_ipv6}{self.protocol_str}",
            f" -p {port}",
            f" -B {server_ip}",
            f" -f k{parallel}",
            f" -i {self.interval}",
            self.server_bandwidth_str(),
            buffer_len,
            window_size,
            print_mss,
            set_mss,
            no_delay,
        ]
        options = "".join(arguments)
        return options
